{
  "id": "ngspice",
  "version": "schemaxis.ngspice/1",
  "adaptor": "schemaxis.adaptors.ngspice.adaptor",
  "runtimeFamily": "47",
  "execution": "Isolated ngspice: verified linear DC networks, linear/logarithmic AC RLC characterisation with branch and input electrical metrics, and first-order RC step response",
  "executables": [],
  "keywords": [
    "circuits",
    "SPICE",
    "DC",
    "AC",
    "RC",
    "frequency",
    "CSV",
    "RL",
    "RLC",
    "inductance",
    "resonance",
    "impedance",
    "logarithmic"
  ],
  "capabilities": "schemaxis.adaptors.ngspice.capabilities:catalogue",
  "executionCapabilities": {
    "modes": [
      "process"
    ],
    "mpi": false
  },
  "consoleTemplate": {
    "version": "schemaxis.ngspice/1",
    "operation": "dcSweep",
    "circuit": {
      "source": "in",
      "resistors": [
        {
          "name": "r1",
          "a": "in",
          "b": "out",
          "resistance": 1000
        },
        {
          "name": "r2",
          "a": "out",
          "b": "0",
          "resistance": 2000
        }
      ],
      "capacitors": [],
      "probes": [
        "out"
      ]
    },
    "start": 0,
    "stop": 5,
    "points": 6
  },
  "routes": {
    "schemaxis.ngspice/1": {
      "module": "schemaxis.adaptors.ngspice.adaptor",
      "schema": "schemaxis.adaptors.ngspice.adaptor:schema",
      "graphEditing": false,
      "workflow": true,
      "compose": true,
      "timeBatches": false,
      "schemaName": "ngspice",
      "acceptedArtifacts": [],
      "scheduled": true,
      "hooks": {
        "query": "schemaxis.adaptors.ngspice.adaptor:query",
        "reusableInputs": "schemaxis.adaptors.ngspice.adaptor:reusableInputs",
        "resources": "schemaxis.adaptors.ngspice.adaptor:resources"
      }
    }
  },
  "consoleCapabilities": {
    "authoredSessions": true,
    "multipleDocuments": true,
    "liveGeometry": false,
    "nativeEditReverseSync": false
  },
  "cliOptions": [
    {
      "flag": "--ngspice",
      "dest": "ngspice",
      "help": "Absolute qualified ngspice-47 executable"
    }
  ]
}
